10	// Message represents an email message to be sent.
11	type Message struct {
12		To      []string // Required: recipient email addresses
13		Cc      []string // Optional: carbon copy recipients
14		Bcc     []string // Optional: blind carbon copy recipients
15		Subject string   // Required: email subject
16		Body    string   // Required: email body content
17		IsHTML  bool     // Whether the body is HTML (default: false for plain text)
18		ReplyTo string   // Optional: reply-to address
19	}
20	
21	// Validate checks that the message has all required fields.
22	func (m *Message) Validate() error {
23		if len(m.To) == 0 {
24			return errors.New("at least one recipient is required")
25		}
26		if m.Subject == "" {
27			return errors.New("subject is required")
28		}
29		if m.Body == "" {
30			return errors.New("body is required")
31		}
32		return nil
33	}
34	
35	// Format creates an RFC 5322 formatted email message.
36	func (m *Message) Format(fromEmail, fromName string) string {
37		var sb strings.Builder
38		fromEmail = sanitizeEmailHeaderValue(fromEmail)
39		fromName = sanitizeEmailHeaderValue(fromName)
40		to := sanitizeEmailHeaderValues(m.To)
41		cc := sanitizeEmailHeaderValues(m.Cc)
42		replyTo := sanitizeEmailHeaderValue(m.ReplyTo)
43		subject := sanitizeEmailHeaderValue(m.Subject)
44	
45		// From header
46		if fromName != "" {
47			fmt.Fprintf(&sb, "From: %s <%s>\r\n", fromName, fromEmail)
48		} else {
49			fmt.Fprintf(&sb, "From: %s\r\n", fromEmail)
50		}
51	
52		// To header
53		fmt.Fprintf(&sb, "To: %s\r\n", strings.Join(to, ", "))
54	
55		// Cc header (optional)
56		if len(cc) > 0 {
57			fmt.Fprintf(&sb, "Cc: %s\r\n", strings.Join(cc, ", "))
58		}
59	
60		// Reply-To header (optional)
61		if replyTo != "" {
62			fmt.Fprintf(&sb, "Reply-To: %s\r\n", replyTo)
63		}
64	
65		// Subject header
66		fmt.Fprintf(&sb, "Subject: %s\r\n", subject)
67	
68		// Date header (RFC 5322 format)
69		fmt.Fprintf(&sb, "Date: %s\r\n", time.Now().Format(time.RFC1123Z))
70	
71		// MIME headers
72		sb.WriteString("MIME-Version: 1.0\r\n")
73	
74		// Content-Type header
75		if m.IsHTML {
76			sb.WriteString("Content-Type: text/html; charset=utf-8\r\n")
77		} else {
78			sb.WriteString("Content-Type: text/plain; charset=utf-8\r\n")
79		}
80	
81		// Empty line separating headers from body
82		sb.WriteString("\r\n")
83	
84		// Body
85		sb.WriteString(m.Body)
86	
87		return sb.String()
88	}
89	
90	func sanitizeEmailHeaderValue(value string) string {
91		value = strings.NewReplacer("\r", " ", "\n", " ").Replace(value)
92		return strings.Join(strings.Fields(value), " ")
93	}
94	
95	func sanitizeEmailHeaderValues(values []string) []string {
96		sanitized := make([]string, 0, len(values))
97		for _, value := range values {
98			sanitized = append(sanitized, sanitizeEmailHeaderValue(value))
99		}
100		return sanitized
101	}
102	
103	// GetAllRecipients returns all recipients (To, Cc, Bcc) as a single slice.
104	func (m *Message) GetAllRecipients() []string {
105		var recipients []string
106		recipients = append(recipients, m.To...)
107		recipients = append(recipients, m.Cc...)
108		recipients = append(recipients, m.Bcc...)
109		return recipients
110	}
